000115 |     private static DateRange resolveRange(PensionBatchExportRequest request) {
000116 |         if (request.getRunMode() == null) {
000117 |             throw new IllegalArgumentException("日次または月次を指定してください。");
000118 |         }
000119 |         if (request.getRunMode() == PensionBatchRunMode.DAILY) {
000120 |             String day = requiredDate(request.getDailyDate(), "年月日を入力してください。");
000121 |             return new DateRange(day, day);
000122 |         }
000123 |         String from = requiredDate(request.getMonthStart(), "月初日を入力してください。");
000124 |         String to = requiredDate(request.getMonthEnd(), "月末日を入力してください。");
000125 |         if (from.compareTo(to) > 0) {
000126 |             throw new IllegalArgumentException("月初日は月末日以前で指定してください。");
000127 |         }
000128 |         return new DateRange(from, to);
000129 |     }
000130 | 
000131 |     private static String requiredDate(String value, String message) {
000132 |         if (value == null || value.trim().length() == 0) {
000133 |             throw new IllegalArgumentException(message);
000134 |         }
000135 |         return DateUtil.toIsoDate(value);
000136 |     }
