000138 |     private static Integer parseStaffNo(String value) {
000139 |         String text = value == null ? "" : value.trim();
000140 |         if (text.length() == 0 || "ALL".equalsIgnoreCase(text)) {
000141 |             return null;
000142 |         }
000143 |         try {
000144 |             return Integer.valueOf(text);
000145 |         } catch (NumberFormatException e) {
000146 |             throw new IllegalArgumentException("職員番号は数値で入力してください。", e);
000147 |         }
000148 |     }
000149 | 
000150 |     private static List<ExportSpec> selectedSpecs(PensionBatchExportRequest request,
000151 |             boolean staffSpecified) {
000152 |         List<ExportSpec> specs = new ArrayList<ExportSpec>();
000153 |         if (request.isIncludeNew()) {
000154 |             specs.add(buildSpec(AuditType.NEW, request.getRunMode(), staffSpecified));
000155 |         }
000156 |         if (request.isIncludeChanged()) {
000157 |             specs.add(buildSpec(AuditType.CHANGED, request.getRunMode(), staffSpecified));
000158 |         }
000159 |         if (request.isIncludeDeleted()) {
000160 |             specs.add(buildSpec(AuditType.DELETED, request.getRunMode(), staffSpecified));
000161 |         }
000162 |         return specs;
000163 |     }
000164 | 
000165 |     private static ExportSpec buildSpec(AuditType type, PensionBatchRunMode mode,
000166 |             boolean staffSpecified) {
000167 |         int base;
000168 |         if (mode == PensionBatchRunMode.DAILY) {
000169 |             base = staffSpecified ? 10 : 40;
000170 |         } else {
000171 |             base = staffSpecified ? 70 : 100;
000172 |         }
000173 |         int queryNumber = base + (type == AuditType.NEW ? 0
000174 |                 : type == AuditType.CHANGED ? 10 : 20);
000175 |         String number = queryNumber < 100 ? "0" + queryNumber : Integer.toString(queryNumber);
000176 |         String category = type.getDisplayName();
000177 |         String queryName = "Q" + number + "_Excel出力_年金予約_" + category
000178 |                 + "_データ明細リスト";
000179 |         String scope = staffSpecified ? "担当者別" : "全担当者";
000180 |         String period = mode == PensionBatchRunMode.DAILY ? "日次" : "月次";
000181 |         String fileName = "年金予約【" + category + "】データ明細リスト（"
000182 |                 + scope + period + "）.xlsx";
000183 |         return new ExportSpec(type, queryName, fileName, category + "分データ",
000184 |                 "年金予約【" + category + "】データ明細リスト");
000185 |     }
000186 | 
000187 |     private static String emptyMessage(AuditType type, PensionBatchRunMode mode,
000188 |             boolean staffSpecified) {
000189 |         String period = mode == PensionBatchRunMode.DAILY ? "日次" : "月次";
000190 |         if (staffSpecified) {
000191 |             return "入力した担当者の【" + type.getDisplayName() + "分（" + period
000192 |                     + "）】の該当明細はありませんでした";
000193 |         }
000194 |         String dateText = mode == PensionBatchRunMode.DAILY ? "入力年月日の" : "入力年月の";
000195 |         return dateText + "【" + type.getDisplayName() + "分（" + period
000196 |                 + "）】の該当明細はありませんでした";
000197 |     }
000198 | 
000199 |     private static void sortAudits(List<PensionAuditRecord> audits) {
000200 |         Collections.sort(audits, new Comparator<PensionAuditRecord>() {
000201 |             public int compare(PensionAuditRecord left, PensionAuditRecord right) {
000202 |                 PensionReservation a = left.getReservation();
000203 |                 PensionReservation b = right.getReservation();
000204 |                 int branch = compareInteger(a.getBranchNo(), b.getBranchNo());
000205 |                 if (branch != 0) {
000206 |                     return branch;
000207 |                 }
000208 |                 int customer = compareInteger(a.getCustomerNo(), b.getCustomerNo());
000209 |                 return customer != 0 ? customer : Long.valueOf(left.getAuditId())
000210 |                         .compareTo(Long.valueOf(right.getAuditId()));
000211 |             }
000212 |         });
000213 |     }
000214 | 
000215 |     private static int compareInteger(Integer left, Integer right) {
000216 |         if (left == null) {
000217 |             return right == null ? 0 : -1;
000218 |         }
000219 |         return right == null ? 1 : left.compareTo(right);
000220 |     }

