000027 |     private static volatile DataSource customerCached;
000028 | 
000029 |     private NenkinDataSource() {
000030 |     }
000031 | 
000032 |     static Connection openConnection() throws SQLException {
000033 |         DataSource dataSource = businessCached;
000034 |         if (dataSource == null) {
000035 |             synchronized (NenkinDataSource.class) {
000036 |                 dataSource = businessCached;
000037 |                 if (dataSource == null) {
