000050 |             synchronized (NenkinDataSource.class) {
000051 |                 dataSource = staffCached;
000052 |                 if (dataSource == null) {
000053 |                     dataSource = lookup(STAFF_JNDI_NAMES,
000054 |                             "N2職員名簿用JNDI DataSourceを取得できません。");
000055 |                     staffCached = dataSource;
