000076 | 
000077 |     private static DataSource lookup(String[] jndiNames, String message) throws SQLException {
000078 |         NamingException last = null;
000079 |         for (int i = 0; i < jndiNames.length; i++) {
000080 |             try {
000081 |                 Object value = new InitialContext().lookup(jndiNames[i]);
000082 |                 if (value instanceof DataSource) {
000083 |                     return (DataSource) value;
000084 |                 }
000085 |             } catch (NamingException e) {
000086 |                 last = e;
000087 |             }
000088 |         }
000089 |         SQLException failure = new SQLException(message);
000090 |         if (last != null) {
000091 |             failure.initCause(last);
000092 |         }
000093 |         throw failure;
000094 |     }
000095 | }

