000025 | 	private static final String[] JNDI_NAMES = {
000026 | 		"jdbc/Oracle_SP2NM", "jdbc/Oracle_DWH", "jdbc/RAROA_DB", "jdbc/RAROA_SHARE"
000027 | 	};
