000029 | 	private JdbcDataSource dataSource;
000030 | 
000031 | 	public void contextInitialized(ServletContextEvent event) {
000032 | 		ServletContext context = event.getServletContext();
000033 | 		if (!Boolean.parseBoolean(System.getProperty(LOCAL_DATABASE_PROPERTY, "false"))) {
000034 | 			context.log("Local H2 compatibility database is disabled; using the N2 container JNDI database.");
000035 | 			return;
000036 | 		}
000037 | 		try {
000038 | 			File databaseFile = resolveDatabaseFile(context);
000039 | 			File directory = databaseFile.getParentFile();
000040 | 			if (!directory.exists() && !directory.mkdirs()) {
000041 | 				throw new IllegalStateException("Cannot create database directory: " + directory);
000042 | 			}
000043 | 
000044 | 			dataSource = new JdbcDataSource();
000045 | 			dataSource.setURL(createJdbcUrl(databaseFile));
000048 | 			initializeDatabase(context);
000049 | 			bindDataSource();
000050 | 			context.log("N2 pension compatibility database initialized: " + databaseFile.getAbsolutePath());
000051 | 		} catch (Exception e) {
000052 | 			context.log("N2 pension compatibility database initialization failed.", e);
000053 | 			throw new IllegalStateException("Database initialization failed.", e);
000054 | 		}
000055 | 	}
000056 | 
000057 | 	public void contextDestroyed(ServletContextEvent event) {
000058 | 		if (dataSource == null) return;
000059 | 		unbindDataSource();
000060 | 		shutdownDatabase(event.getServletContext());
000061 | 	}
000062 | 
000063 | 	private File resolveDatabaseFile(ServletContext context) {
000064 | 		String overridePath = System.getProperty("n2nenkin.db.path");
000065 | 		if (overridePath != null && overridePath.trim().length() > 0) {
000066 | 			return new File(overridePath.trim()).getAbsoluteFile();
000067 | 		}
000068 | 		String directory = context.getRealPath("/WEB-INF/local-db");
000069 | 		if (directory == null) throw new IllegalStateException("Expanded deployment is required for local H2.");
000070 | 		return new File(directory, "nenkin").getAbsoluteFile();
000071 | 	}
000072 | 
000073 | 	private String createJdbcUrl(File databaseFile) {
000074 | 		return "jdbc:h2:file:" + databaseFile.getAbsolutePath().replace('\\', '/')
000075 | 			+ ";MODE=Oracle;DATABASE_TO_UPPER=TRUE;CASE_INSENSITIVE_IDENTIFIERS=FALSE";
000076 | 	}
